"""Command-line interface for frozen TPTM evidence and hybrid review routing."""

from __future__ import annotations

import argparse
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import socket
import sys
import time
from typing import Sequence

from .canonical import (
    CanonicalizationError,
    canonical_json_bytes,
    ruleset_sha256,
    semantic_result_bytes,
)
from .codes import ANALYSIS_VERSION, RUN_ENVELOPE_SCHEMA_VERSION
from .hybrid import HYBRID_PROTOCOL_ID, HybridRoutingState, hybrid_route
from .model import RunEnvelope
from .pipeline import (
    ResultValidationError,
    analyze_manifest_bytes,
    result_exit_code,
    validate_result_bytes,
)
from .review import (
    build_review_packet,
    review_packet_bytes,
    validate_review_decision_bytes,
    validate_review_packet_bytes,
)


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Frozen G0-G8 TPTM evidence and high-recall hybrid routing"
    )
    subparsers = parser.add_subparsers(dest="operation", required=True)

    analyze = subparsers.add_parser("analyze-manifest")
    analyze.add_argument("--candidate", type=Path, required=True)
    analyze.add_argument("--repository-path", type=Path)
    analyze.add_argument("--output", type=Path, required=True)
    analyze.add_argument("--run-envelope", type=Path, required=True)

    validate = subparsers.add_parser("validate-result")
    validate.add_argument("--result", type=Path, required=True)

    replay = subparsers.add_parser("replay")
    replay.add_argument("--candidate", type=Path, required=True)
    replay.add_argument("--repository-path", type=Path)
    replay.add_argument("--expected", type=Path)
    replay.add_argument("--output", type=Path)
    replay.add_argument("--runs", type=int, default=3)

    build_packet = subparsers.add_parser("build-review-packet")
    build_packet.add_argument("--result", type=Path, required=True)
    build_packet.add_argument("--output", type=Path, required=True)

    validate_packet = subparsers.add_parser("validate-review-packet")
    validate_packet.add_argument("--packet", type=Path, required=True)

    validate_decision = subparsers.add_parser("validate-review-decision")
    validate_decision.add_argument("--decision", type=Path, required=True)
    validate_decision.add_argument("--review-packet", type=Path, required=True)

    route = subparsers.add_parser("hybrid-route")
    route.add_argument("--result", type=Path, required=True)
    route.add_argument("--output", type=Path)

    hybrid_replay = subparsers.add_parser("hybrid-replay")
    hybrid_replay.add_argument("--semantic-directory", type=Path, required=True)
    hybrid_replay.add_argument("--case-specifications", type=Path, required=True)
    hybrid_replay.add_argument("--output", type=Path)
    hybrid_replay.add_argument("--packet-output-directory", type=Path)

    subparsers.add_parser("print-ruleset-hash")
    return parser


def _utc_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="microseconds").replace(
        "+00:00", "Z"
    )


def _write(path: Path, encoded: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(encoded)


def _analyze(arguments: argparse.Namespace) -> int:
    started_at = _utc_now()
    monotonic_start = time.monotonic_ns()
    exit_code = 5
    try:
        result = analyze_manifest_bytes(
            arguments.candidate.read_bytes(),
            repository_path=arguments.repository_path,
        )
        encoded = semantic_result_bytes(result)
        _write(arguments.output, encoded)
        exit_code = result_exit_code(result)
        return exit_code
    finally:
        finished_at = _utc_now()
        duration_ms = max(0, (time.monotonic_ns() - monotonic_start) // 1_000_000)
        envelope = RunEnvelope(
            schema_version=RUN_ENVELOPE_SCHEMA_VERSION,
            analysis_version=ANALYSIS_VERSION,
            operation="analyze-manifest",
            input_path=str(arguments.candidate),
            output_path=str(arguments.output),
            started_at_utc=started_at,
            finished_at_utc=finished_at,
            hostname=socket.gethostname(),
            pid=os.getpid(),
            duration_ms=duration_ms,
            exit_code=exit_code,
        )
        _write(arguments.run_envelope, canonical_json_bytes(envelope))


def _validate(arguments: argparse.Namespace) -> int:
    result = validate_result_bytes(arguments.result.read_bytes())
    print(result.semantic_sha256)
    return 0


def _replay(arguments: argparse.Namespace) -> int:
    if arguments.runs < 2:
        raise ResultValidationError("replay requires at least two runs")
    candidate_bytes = arguments.candidate.read_bytes()
    results = [
        analyze_manifest_bytes(
            candidate_bytes,
            repository_path=arguments.repository_path,
        )
        for _ in range(arguments.runs)
    ]
    encoded_results = [semantic_result_bytes(result) for result in results]
    if any(encoded != encoded_results[0] for encoded in encoded_results[1:]):
        raise ResultValidationError("replay produced non-identical semantic bytes")
    if arguments.expected is not None:
        expected = arguments.expected.read_bytes()
        validate_result_bytes(expected)
        if expected != encoded_results[0]:
            raise ResultValidationError("replay differs from the expected semantic result")
    if arguments.output is not None:
        _write(arguments.output, encoded_results[0])
    print(
        json.dumps(
            {
                "byte_identical": True,
                "runs": arguments.runs,
                "semantic_sha256": results[0].semantic_sha256,
            },
            sort_keys=True,
            separators=(",", ":"),
        )
    )
    return result_exit_code(results[0])


def _build_review_packet(arguments: argparse.Namespace) -> int:
    result = validate_result_bytes(arguments.result.read_bytes())
    packet = build_review_packet(result)
    _write(arguments.output, review_packet_bytes(packet))
    print(packet.review_packet_sha256)
    return 0


def _validate_review_packet(arguments: argparse.Namespace) -> int:
    packet = validate_review_packet_bytes(arguments.packet.read_bytes())
    print(packet.review_packet_sha256)
    return 0


def _validate_review_decision(arguments: argparse.Namespace) -> int:
    packet = validate_review_packet_bytes(arguments.review_packet.read_bytes())
    decision = validate_review_decision_bytes(arguments.decision.read_bytes(), packet)
    print(decision.review_decision_sha256)
    return 0


def _hybrid_route(arguments: argparse.Namespace) -> int:
    result = validate_result_bytes(arguments.result.read_bytes())
    encoded = canonical_json_bytes(hybrid_route(result))
    if arguments.output is None:
        sys.stdout.buffer.write(encoded)
    else:
        _write(arguments.output, encoded)
    return 0


def _rate(numerator: int, denominator: int) -> str:
    if denominator < 1:
        raise ResultValidationError("hybrid replay requires at least one case")
    scaled = (numerator * 1_000_000 + denominator // 2) // denominator
    return f"{scaled // 1_000_000}.{scaled % 1_000_000:06d}"


def _case_classes(path: Path) -> dict[str, str]:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (UnicodeError, json.JSONDecodeError) as error:
        raise ResultValidationError("case specifications are not UTF-8 JSON") from error
    if not isinstance(value, dict) or not isinstance(value.get("cases"), list):
        raise ResultValidationError("case specifications must contain a cases array")
    classes: dict[str, str] = {}
    for item in value["cases"]:
        if not isinstance(item, dict):
            raise ResultValidationError("case specification rows must be objects")
        case_id = item.get("case_id")
        gold_class = item.get("gold_class")
        if (
            not isinstance(case_id, str)
            or not case_id
            or gold_class not in {"POSITIVE", "DIFFICULT_NEGATIVE"}
            or case_id in classes
        ):
            raise ResultValidationError("case specification identity is invalid")
        classes[case_id] = gold_class
    if value.get("case_count") != len(classes):
        raise ResultValidationError("case specification count is inconsistent")
    return classes


def _hybrid_replay(arguments: argparse.Namespace) -> int:
    classes = _case_classes(arguments.case_specifications)
    semantic_files = tuple(sorted(arguments.semantic_directory.glob("*.json")))
    if {path.stem for path in semantic_files} != set(classes):
        raise ResultValidationError(
            "semantic result files do not match the case specifications"
        )

    route_counts = {state.value: 0 for state in HybridRoutingState}
    class_counts = {
        "POSITIVE": {state.value: 0 for state in HybridRoutingState},
        "DIFFICULT_NEGATIVE": {state.value: 0 for state in HybridRoutingState},
    }
    packet_manifest = []
    evidence_integrity_cases = 0
    deterministic_packets = 0

    for path in semantic_files:
        encoded_result = path.read_bytes()
        result = validate_result_bytes(encoded_result)
        if result.candidate_id != path.stem:
            raise ResultValidationError("semantic filename and candidate ID differ")
        state = hybrid_route(result).state
        route_counts[state.value] += 1
        class_counts[classes[path.stem]][state.value] += 1
        evidence_integrity_cases += 1
        if state is not HybridRoutingState.STRUCTURED_REVIEW_REQUIRED:
            continue

        packet_runs = tuple(
            review_packet_bytes(build_review_packet(validate_result_bytes(encoded_result)))
            for _ in range(3)
        )
        if packet_runs[0] != packet_runs[1] or packet_runs[0] != packet_runs[2]:
            raise ResultValidationError("review packet replay is not byte-identical")
        packet = validate_review_packet_bytes(packet_runs[0])
        deterministic_packets += 1
        output_relative = None
        if arguments.packet_output_directory is not None:
            filename = (
                f"{result.queue_position:06d}-"
                f"{hashlib.sha256(result.candidate_id.encode('utf-8')).hexdigest()[:16]}.json"
            )
            _write(arguments.packet_output_directory / filename, packet_runs[0])
            output_relative = filename
        packet_manifest.append(
            {
                "candidate_id": result.candidate_id,
                "packet_path": output_relative,
                "review_packet_sha256": packet.review_packet_sha256,
            }
        )

    total = len(semantic_files)
    review_count = route_counts[HybridRoutingState.STRUCTURED_REVIEW_REQUIRED.value]
    auto_retain_count = route_counts[
        HybridRoutingState.AUTO_RETAIN_FOR_CONSTRUCTION.value
    ]
    auto_reject_count = route_counts[
        HybridRoutingState.AUTO_MECHANICAL_REJECT.value
    ]
    positive = class_counts["POSITIVE"]
    positive_total = sum(positive.values())
    positive_high_recall_routes = (
        positive[HybridRoutingState.AUTO_RETAIN_FOR_CONSTRUCTION.value]
        + positive[HybridRoutingState.STRUCTURED_REVIEW_REQUIRED.value]
    )
    prohibited_positive_routes = positive_total - positive_high_recall_routes
    report = {
        "AUTO_MECHANICAL_REJECT_RATE": _rate(auto_reject_count, total),
        "AUTO_RETAIN_RATE": _rate(auto_retain_count, total),
        "REVIEW_RATE": _rate(review_count, total),
        "case_count": total,
        "development_evidence_only": True,
        "deterministic_replay": {
            "byte_identical_packet_count": deterministic_packets,
            "fresh_builds_per_packet": 3,
            "rate": _rate(deterministic_packets, review_count),
            "review_packet_count": review_count,
        },
        "difficult_negative_routing": class_counts["DIFFICULT_NEGATIVE"],
        "evidence_integrity": {
            "cases_passed": evidence_integrity_cases,
            "error_count": 0,
            "rate": _rate(evidence_integrity_cases, total),
            "total_cases": total,
        },
        "packet_manifest": packet_manifest,
        "positive_routing": {
            "high_recall_route_count": positive_high_recall_routes,
            "prohibited_route_count": prohibited_positive_routes,
            "recall": _rate(positive_high_recall_routes, positive_total),
            "routes": positive,
            "total": positive_total,
        },
        "production_access": False,
        "protocol_id": HYBRID_PROTOCOL_ID,
        "route_counts": route_counts,
        "schema_version": "tptm-hybrid-development-replay-v1",
        "workload": {
            "median_review_time_ms": None,
            "p95_review_time_ms": None,
            "review_time_status": "NOT_MEASURED_NO_REVIEWS_PERFORMED",
            "reviewer_disagreement_rate": None,
            "second_review_rate": None,
            "structured_review_percentage": _rate(review_count, total),
        },
    }
    encoded = canonical_json_bytes(report)
    if arguments.output is None:
        sys.stdout.buffer.write(encoded)
    else:
        _write(arguments.output, encoded)
    return 0 if prohibited_positive_routes == 0 else 1


def main(argv: Sequence[str] | None = None) -> int:
    arguments = _parser().parse_args(argv)
    try:
        if arguments.operation == "analyze-manifest":
            return _analyze(arguments)
        if arguments.operation == "validate-result":
            return _validate(arguments)
        if arguments.operation == "replay":
            return _replay(arguments)
        if arguments.operation == "build-review-packet":
            return _build_review_packet(arguments)
        if arguments.operation == "validate-review-packet":
            return _validate_review_packet(arguments)
        if arguments.operation == "validate-review-decision":
            return _validate_review_decision(arguments)
        if arguments.operation == "hybrid-route":
            return _hybrid_route(arguments)
        if arguments.operation == "hybrid-replay":
            return _hybrid_replay(arguments)
        if arguments.operation == "print-ruleset-hash":
            print(ruleset_sha256())
            return 0
        raise AssertionError(arguments.operation)  # pragma: no cover
    except (
        CanonicalizationError,
        ResultValidationError,
        OSError,
        TypeError,
        ValueError,
    ) as error:
        print(f"TPTM_ERROR: {error}", file=sys.stderr)
        return 5


if __name__ == "__main__":  # pragma: no cover
    raise SystemExit(main())

